    }

    function run(bytes32 hash, uint amount) public payable {
        require(amount == 1 ether);
        require(address(this).balance >= amount);

        c.lockInGuess{value: amount}(hash);

        (uint lockedBlock, bytes32 storedGuess) = c.guesses(address(this));

        bool settleReverted;
        try c.settle() {
