contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash, uint lockValue, uint blockDelta) public payable {
        require(lockValue == 1 ether);
        require(address(this).balance >= lockValue);
        c.lockInGuess{value: lockValue}(guessHash);

        // The lock block is now set to the block of lockInGuess + 1.
        // advance to a block beyond it by contract-deploying a new C at a later block (not allowed),
        // so instead rely on the fact that settle()'s block.number > guesses[msg.sender].block
        // cannot be satisfied at block exactly equal to the recorded block.
        // We test the boundary: calling settle() in the very next block should revert.
        // However we cannot call it at the exact lock block from here.  
        // To exercise the after-lock path we must make the deciding call in a later transaction.
        // Since the checker runs run(...) exactly once, we accept that settle() here can only
        // either revert (still at the lock block) or succeed.
        bool settledReverted;
        uint cBalanceBefore = address(c).balance;
        try c.settle() {
            settledReverted = false;
        } catch {
            settledReverted = true;
        }
        uint cBalanceAfter = address(c).balance;

        // General rule: if settle() succeeds, the contract must have paid out exactly 2 ether
        // (c's balance decreases by 2 ether) only when the guess matched the blockhash.
        // If the guess does not match, c's balance must remain unchanged (no payout).
        // We cannot read the guess matching directly, but we can assert the logical invariant:
        // settle() either reverts (no state change) or moves exactly 0 or 2 ether out of c.
        assert(
            settledReverted
                ? (cBalanceAfter == cBalanceBefore)
                : (cBalanceAfter == cBalanceBefore || cBalanceAfter + 2 ether == cBalanceBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 guessHash) public payable {
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(guessHash);

        bool firstReverted;
        try c.settle() { firstReverted = false; } catch { firstReverted = true; }

        // After settle(), the caller's lock is either cleared (so a second settle reverts)
        // or the first settle reverted due to timing.
        bool secondReverted;
        try c.settle() { secondReverted = false; } catch { secondReverted = true; }

        // General rule: calling settle() twice cannot both succeed; the lock is consumed.
        // If the first settle succeeded, the second must revert because the lock is cleared.
        assert(firstReverted || secondReverted);
    }

    receive() external payable {}
}

